    /** 运行监测读数（合成数据）。 */
    public record ReadingRequest(
            @NotNull(message = "载荷读数不能为空") Integer loadValue,
            @NotNull(message = "速度读数不能为空") Integer speedValue) {
    }

    /** 统一错误响应体。 */
    public record ErrorBody(String error, String message) {
    }
}

